        let rows: &[(&str, String, String)] = &[
            (
                "a bare account id",
                r#"{"Statement":[{"Principal":{"AWS":"210987654321"}}]}"#.to_string(),
                format!(r#"{{"Statement":[{{"Principal":{{"AWS":"{root}"}}}}]}}"#),
            ),
