/// Why a batch request is refused as a whole, before any entry is looked at.
#[derive(Debug, PartialEq, Eq)]
pub enum BatchRequestRefusal {
    /// The batch carries no entries (`EmptyBatchRequest`).
    Empty(String),
    /// The batch carries more than [`MAX_BATCH_ENTRIES`] entries
    /// (`TooManyEntriesInBatchRequest`).
    TooManyEntries(String),
    /// An entry's `Id` is not one the specification admits (`InvalidBatchEntryId`).
    InvalidEntryId(String),
    /// Two entries carry the same `Id` (`BatchEntryIdsNotDistinct`).
    EntryIdsNotDistinct(String),
}

/// The whole-request refusal the entry `ids` of an `operation` batch earn, if any.
///
/// Entries are judged in request order, so the first one that is malformed or repeats an
/// earlier id decides the refusal.
pub fn batch_request_refusal<'a>(
    operation: &str,
    ids: impl ExactSizeIterator<Item = &'a str>,
) -> Result<(), BatchRequestRefusal> {
    if ids.len() == 0 {
        return Err(BatchRequestRefusal::Empty(empty_batch_message(operation)));
    }
    if ids.len() > MAX_BATCH_ENTRIES {
        return Err(BatchRequestRefusal::TooManyEntries(format!(
            "Maximum number of entries per request are {MAX_BATCH_ENTRIES}. You have sent {}.",
            ids.len()
        )));
    }
    let mut seen = BTreeSet::new();
    for id in ids {
        if !is_valid_batch_entry_id(id) {
            return Err(BatchRequestRefusal::InvalidEntryId(format!(
                "A batch entry id can only contain alphanumeric characters, hyphens \
                 and underscores. It can be at most {MAX_BATCH_ENTRY_ID_LEN} letters long."
            )));
        }
        if !seen.insert(id) {
            return Err(BatchRequestRefusal::EntryIdsNotDistinct(format!(
                "Id {id} repeated."
            )));
        }
    }
    Ok(())
}
